async function chapterView(number){if(state.chapter!==number)state.selectedRefs.clear();if(reqProject())return heading(`CHAPTER 0${number}`,'Academic Writing Studio','Choose a research project first.')+reqProject();state.chapter=number;await loadRefs();if(number===1)await loadNews();let chapters=await api(`/api/v09/projects/${state.project.id}/chapters/${number}`);state.chapterVersions=chapters;let latest=chapters[0];const names=['','Introduction & Phenomena','Literature Review','Research Methodology','Findings & Discussion'];let key=state.project.id+':chapter'+number;let prefill=state.editorDrafts[key]??latest?.body??'';let previousSelection=latest?.reference_ids||[];if(!state.referenceSelections[key]&&previousSelection.length)state.selectedRefs=new Set(previousSelection.filter(id=>state.refs.some(r=>r.id===id)));let status=latest?.status||'not started';state.currentCitationStyle=latest?.citation_style||'apa';let extras=number===1?`<details><summary>Phenomena Finder · related to your dataset</summary><p class="hint">Suggested research questions are not factual claims. Search and verify news separately.</p><button data-action="find-phenomena" class="btn light sm">Suggest research phenomena</button><div id="phenomenaResults"></div>${sep}<form id="newsSearchForm">${field('News search terms','newsQuery','e.g., Indonesia social commerce trust')}<button class="btn sm" type="submit">Search news</button></form><div id="newsSearchResults" class="scrollbox"></div>${sep}<h3>Save verified article link</h3><form id="addNewsForm">${field('Article title','newsTitle','Article headline')}${field('Article HTTPS URL','newsURL','https://publisher.com/article')}${field('Source / outlet','newsSource','National news organization')}<button class="btn sm light" type="submit">Save news lead</button></form><h3 class="sectiongap">Saved news leads</h3><div class="scrollbox">${state.news.map(n=>`<div class="newsrow"><b>${html(n.title)}</b><small>${html(n.source)}</small><div class="row"><a href="${attr(n.url)}" target="_blank" rel="noopener noreferrer">Open source ↗</a><button data-action="delete-news" data-id="${attr(n.id)}" class="btn sm danger">Remove</button></div></div>`).join('')||'<p class="hint">No news saved.</p>'}</div></details>`:number===2?`<details><summary>Literature synthesis &amp; research gap</summary><p class="hint">Only references you select below will be provided to the AI. Bibliographic metadata alone cannot verify article findings.</p>${btn('Build evidence map','evidence-map','light')}<div id="evidenceMap"></div></details>`:number===3?`<details><summary>Methodology checklist</summary><div class="checklist"><span>□ Design and unit of analysis</span><span>□ Population and sampling evidence</span><span>□ Instrument and scale coding</span><span>□ Consent and ethical approval (if applicable)</span><span>□ Sample size, exclusions and preprocessing</span><span>□ Model specification, seeds and bootstrap settings</span></div></details>`:`<details><summary>Analysis integrity requirements</summary><p class="hint">Chapter 4 AI generation is blocked if SEM-PLS results are missing or stale. A saved manual draft is allowed, but must not falsely claim analysis outcomes.</p><span class="badge ${state.project.analysis?.status==='current'?'current':'stale'}">${html(state.project.analysis?.status||'No analysis')}</span><button data-view="sem" class="btn sm light">Open analysis</button></details>`;
 return heading(`CHAPTER 0${number} · ACADEMIC WRITING`,names[number],`Compose, cite and generate with selected references. Editable drafts are versioned; AI never overwrites prior versions without your action.`,btn('View draft versions','draft-versions','light'))+guideBar(4)+
 `<div class="writing-grid"><div class="panel"><div class="panelhead"><h2>Research manuscript editor</h2><span class="badge ${status==='current'?'current':status==='stale'||status==='needs_review'?'stale':status==='broken_citation'?'bad':''}">${html(status)}</span></div><div class="row"><div class="row">${btn('Save version','save-chapter','light')}${btn('Insert bibliography','insert-bibliography','light')}${btn('Export Word','export-chapter-word','light')}</div><span class="hint" id="wordCount">0 words</span></div>${latest?.unlinked_author_year_candidates?.length?hint('Possible manually typed author-year citations were detected. Open Integrity & History to review them; replace with Cite+ linked citations before submission.','warning'):''}${latest?.citation_integrity==='legacy_numeric_needs_review'||latest?.citation_integrity==='mixed_linked_and_legacy_needs_review'?hint('This saved chapter contains old numeric citations. Reinsert them using Cite+ to link each source; numbering cannot be verified from plain text.','warning'):''}${status==='broken_citation'?hint('Broken citation: a reference used by this chapter has been removed from the library. Restore/replace the source and review in-text citations before submission.','warning'):status==='needs_review'?hint('Legacy draft: verify the references and save a new version to establish citation provenance.','warning'):''}<textarea class="editor sectiongap" id="chapterEditor" aria-label="Chapter editor" placeholder="Start drafting here, or generate text after selecting verified sources.\n\nClick Cite to insert a linked reference token; the preview and Word export display the final citation.">${html(prefill)}</textarea><details class="sectiongap" open><summary>Live citation preview (final formatting)</summary><p class="hint">Linked tokens keep IEEE numbering and bibliography synchronized, even if sources are unchecked or citations are reordered. Only cited references appear in the bibliography. Older plain-text citations may need manual replacement.</p><p id="citationWarnings" class="hint"></p><pre id="citationPreview" class="citation-preview"></pre></details>${extras}<details open><summary>AI drafting instructions</summary>${area('Research facts (only actual, verifiable data)','researchFacts','Population, instrument, sampling and verified methods…','',4)}${area('Specific drafting instructions','writingInstructions','Sections, target journal style, arguments to develop…','',3)}<div class="grid cols3"><div class="field"><label>Language</label><select id="draftLanguage"><option value="English">English</option><option value="Indonesian">Indonesian</option></select></div><div class="field"><label>Style</label><select id="draftStyle"><option value="apa" ${state.currentCitationStyle==='apa'?'selected':''}>APA</option><option value="ieee" ${state.currentCitationStyle==='ieee'?'selected':''}>IEEE</option><option value="generic">General academic</option><option value="custom">Custom</option></select></div><div class="field"><label>Mode</label><select id="draftMode"><option value="preview">Prompt preview · no AI</option><option value="generate">Generate with connected AI</option></select></div></div><p class="hint">The live preview and Word export resolve linked references in first-citation order. Changing APA/IEEE automatically re-renders linked citations; plain-text legacy citations require manual review.</p><div class="row"><button class="btn primary" data-action="generate-chapter" id="generateBtn">Preview / Generate chapter</button><button class="btn light" data-action="download-chapter">Download .txt</button></div><div id="generationResult" class="sectiongap"></div></details></div>
 <aside class="panel reference-rail"><div class="panelhead"><h2>Source citations</h2><span class="badge">${state.refs.length}</span></div><p class="hint">✓ Check sources to include in AI context. Click Cite or drag a source to insert a linked reference token. Citation preview and Word export show formatted references.</p><input id="chapterRefFilter" class="control" placeholder="Search your references…"><div id="chapterReferenceList" class="scrollbox">${chapterReferences(state.refs)}</div><div class="sectiongap"><button class="btn light sm" data-action="add-reference">+ Add reference</button></div><div class="notice sectiongap">Reference inclusion does not prove a source supports a specific statement. Read the source and verify every citation.</div></aside></div>`;
}
function chapterReferences(refs){return refs.length?refs.map(r=>`<div class="refrow" draggable="true" data-drag-ref="${attr(r.id)}"><input type="checkbox" data-select-ref="${attr(r.id)}" ${state.selectedRefs.has(r.id)?'checked':''} title="Include reference in AI context"><div><b>${html(r.title)}</b><small>${html(r.authors||'Unknown author')} · ${html(r.year||'n.d.')}</small></div><button data-action="cite" data-id="${attr(r.id)}" title="Insert in-text citation">Cite +</button></div>`).join(''):empty('Reference library is empty','Tambahkan sumber dari Referensi Ilmiah.');}
async function auditView(){if(reqProject())return reqProject();let a=await api(`/api/v09/projects/${state.project.id}/audit`);return heading('QUALITY CONTROL','Research Integrity & History','View reproducibility metadata, stale results, missing prerequisites and the recorded project event timeline.',btn('Export reproducibility JSON','export-provenance','light'))+
 `<div class="grid cols3"><div class="panel metric"><span>Model revision</span><strong>${a.model_revision}</strong><small>Tracked project updates</small></div><div class="panel metric"><span>Analysis status</span><strong style="font-size:18px">${html(a.analysis_status)}</strong><small>Linked to dataset/model SHA-256</small></div><div class="panel metric"><span>Audit checks</span><strong>${a.alerts.length}</strong><small>Warnings are not external validation</small></div></div>`+
 `<div class="grid cols2 sectiongap">${panel('Integrity checklist',a.alerts.length?a.alerts.map(x=>`<div class="callout ${x.severity==='blocker'?'warning':''}" style="margin-bottom:9px"><b>${html(x.severity)}</b>: ${html(x.message)}</div>`).join(''):hint('No automated blockers detected. Human methodological review remains essential.'))}${panel('Draft provenance',Object.keys(a.draft_status).length?Object.entries(a.draft_status).map(([n,v])=>`<div class="listitem"><b>Chapter ${n}</b><span class="badge ${v==='current'?'current':v==='broken_citation'?'bad':'stale'}">${html(v)}</span></div>`).join(''):empty('No chapter versions','Generated and saved versions are tracked separately.'))}</div>`+
 panel('Event timeline',a.events.length?`<div class="scrollbox">${a.events.map(x=>`<div class="listitem"><div><b>${html(x.event_type.replaceAll('_',' '))}</b><small>${html(x.created_at.slice(0,19).replace('T',' '))}</small></div></div>`).join('')}</div>`:empty('No event history','Create a project and begin editing.'))+`<div class="notice sectiongap">SHA-256: <code>${html(a.sha256)}</code></div>`;
}
async function settingsView(){let s=await api('/api/auth/status');state.auth=s;state.providers=await api('/api/ai/providers');return heading('PREFERENCES','AI & Local Account','Use Ollama on your Mac without a secret key, or connect a cloud provider for this session.',btn('Refresh connection','settings-view','light'))+
 `<div class="grid cols2">${panel('AI provider connection',`<div class="row"><span class="badge ${s.provider_connected?'current':''}">${s.provider_connected?'Connected':'Not connected'}</span><span class="hint">${html(s.provider_label||'')}</span></div><form id="connectForm" class="sectiongap"><div class="field"><label>Provider</label><select id="providerSelect">${Object.entries(state.providers).map(([id,p])=>`<option value="${attr(id)}" ${s.provider===id?'selected':''}>${html(p.label)}</option>`).join('')}</select></div>${field('Model ID','providerModel','qwen3:8b',s.model||'qwen3:8b')}${field('Secret API key (leave blank for Ollama)','providerKey','Cloud provider keys are never written to the database','','password')}${field('Custom HTTPS base URL (optional)','providerURL','https://api.provider.com/v1')}<button class="btn" type="submit">Connect AI</button><button type="button" class="btn light" data-action="disconnect-ai">Disconnect</button></form>${hint('For Ollama: choose Ollama (local), set model to qwen3:8b, leave key blank. Local endpoint: http://127.0.0.1:11434. Requests may run up to 1 hour.')}`)}${panel('Account & workspace',`<p><b>Local workspace</b></p><p class="hint">Owner login is designed for one machine only. This is not a hardened multi-user cloud service.</p><div class="callout"><b>Privacy:</b> Local datasets are read by this server. When connecting a cloud AI provider, selected context is sent to that provider. Ollama keeps inference on-device.</div>${sep}<h3>Branding</h3><form id="logoForm"><div class="field"><label>Upload Z-Research logo (PNG/JPG/WebP)</label><input name="file" type="file" accept="image/png,image/jpeg,image/webp"></div><button class="btn light" type="submit">Apply logo</button></form><div class="sectiongap">${btn('Sign out','logout','danger')}</div>`)}</div>`;}
async function render(){let view=state.view;if(!state.auth?.authenticated){await showAuth();return}
 const map={home:overview,data:dataView,model:modelView,sem:semView,library:libraryView,audit:auditView,settings:settingsView};let output=view.startsWith('chapter')?await chapterView(Number(view.slice(-1))):await map[view]();root.innerHTML=output;if(view==='model' && state.project?.model?.edges?.length){api(`/api/v09/projects/${state.project.id}/preview`,'POST',{}).then(o=>{let target=$('#liveModelPreview');if(target)target.innerHTML=panel('Automatic live coefficients · no bootstrap',statTable(['Path','β'],Object.entries(o.paths).map(([k,v])=>[k,fmt(v)]))+'<p class="hint">Quick estimate only; complete SEM-PLS is needed for inference.</p>')}).catch(()=>{})}if(view.startsWith('chapter')){const ed=$('#chapterEditor');if(ed){ed.addEventListener('input',wordCount);wordCount()}}if(view==='settings')$('#providerSelect')?.addEventListener('change',()=>{$('#providerModel').value=state.providers[$('#providerSelect').value]?.default_model||''});}
function citationPreview(){
 const editor=$('#chapterEditor'),pre=$('#citationPreview'),warnings=$('#citationWarnings');
 if(!editor||!pre)return;
 const result=ZRCitation.renderDocument(editor.value,citationStyle(),state.refs);
 pre.textContent=result.text||'(Start writing and inserting sources to preview the final manuscript.)';
 const deselected=result.order.filter(id=>!state.selectedRefs.has(id));
 const notes=[];
 if(result.missing.length)notes.push('Missing references: '+result.missing.join(', '));
 if(deselected.length)notes.push('Cited sources not selected for this chapter: '+deselected.join(', ')+'. Select them before saving.');
 if(result.legacyNumeric)notes.push('Legacy plain-text numeric citation detected: reinsert it using Cite + so numbering can be kept correct.');
 warnings.textContent=notes.join(' · ')||'Linked citations will be numbered by their first appearance, not checkbox order.';
 warnings.className='hint'+(notes.length?' citation-warning':'');
}
const wordCount=()=>{const label=$('#wordCount');if(label)label.textContent=($('#chapterEditor')?.value.trim().split(/\s+/).filter(Boolean).length||0).toLocaleString()+' words';citationPreview()};
async function showAuth(){let s=await api('/api/auth/status');state.auth=s;root.innerHTML=heading('AKUN LOKAL','Selamat datang di Z-Research','Masuk untuk melanjutkan penelitian. Tidak perlu akun cloud atau layanan eksternal.')+panel(s.configured?'Masuk ke Z-Research':'Buat akun pemilik' ,`<form id="loginForm" style="max-width:450px">${field('Nama pengguna','loginName','Nama pengguna Anda')}${field('Kata sandi (minimal 10 karakter)','loginPassword','Gunakan kata sandi yang kuat','','password')}<button class="btn" type="submit">${s.configured?'Masuk':'Buat akun & mulai'}</button></form><p class="hint">Akun dan data disimpan di perangkat server. Ini versi lokal beta, bukan layanan publik.</p>`);}
let previewSequence=0;
function schedulePreview(){clearTimeout(state.previewTimer);const id=++previewSequence;if(!state.project?.dataset_id||!state.project.model?.edges?.length)return;state.previewTimer=setTimeout(async()=>{try{let r=await api(`/api/v09/projects/${state.project.id}/preview`,'POST',{});if(id!==previewSequence)return;let box=$('#liveModel');if(box)box.innerHTML=panel('Automatically refreshed SEM preview',`<p class="hint">${html(r.notice)} · N=${r.n}. No bootstrap significance.</p>${statTable(['Path','β estimate'],Object.entries(r.paths).map(([k,v])=>[k,fmt(v)]))}`);let sem=$('#liveResult');if(sem)sem.innerHTML=panel('Live preview · non-inferential',statTable(['Path','β'],Object.entries(r.paths).map(([k,v])=>[k,fmt(v)])))}catch(ex){let box=$('#liveModel');if(box)box.innerHTML=hint('Preview unavailable: '+html(ex.message),'warning')}},850)}
async function start(){try{state.auth=await api('/api/auth/status');if(state.auth.authenticated){await loadDataset();await loadProjects();await loadRefs()}await render()}catch(e){root.innerHTML=panel('Aplikasi belum terhubung',`<p>${html(e.message)}</p>${btn('Retry','refresh','light')}`)}}
const busy=async(fn)=>{try{await fn()}catch(e){notice(e.message,true)}},navigate=id=>setView(id);
const pickMulti=id=>{const box=$('#'+id);if(box?.matches('select'))return $$('option:checked',box).map(x=>x.value);return $$('[data-multi-for="'+id+'"]:checked').map(x=>x.value)};
function insertCitation(text){let el=$('#chapterEditor');if(!el)return notice('Open a chapter editor first',true);let start=el.selectionStart??el.value.length;let end=el.selectionEnd??start;el.value=el.value.slice(0,start)+text+el.value.slice(end);el.focus();el.setSelectionRange(start+text.length,start+text.length);wordCount();}
async function handleAction(action,el){let p=state.project;switch(action){
 case 'refresh':await start();break;
 case 'new-project':navigate('data');setTimeout(()=>{const d=$('#newProjectPanel');if(d)d.open=true;$('#newProjectName')?.focus()},150);break;
 case 'home-view':navigate('home');break;
 case 'data-view':case 'model-view':case 'sem-view':case 'settings-view':case 'audit-view':navigate(action.split('-')[0]);break;
 case 'edit-dataset':{let did=el.dataset.id;let page=await api(`/api/v05/datasets/${did}/rows?offset=0&limit=8`);let columns=page.columns.slice(0,12);let table=statTable(['Row',...columns],page.rows.map((row,i)=>[String(i+1),...columns.map(c=>String(row[c]??'—'))]));openModal('Edit dataset · audited changes',`<p class="hint">Edits update the working CSV and invalidate old analysis. A copy of the original CSV is preserved on the first edit.</p>${table}<form id="editDatasetForm"><div class="grid cols2"><div class="field"><label>Row number (1–${page.total})</label><input id="editRow" type="number" min="1" max="${page.total}" value="1" required></div><div class="field"><label>Numeric column</label>${selector('editColumn',columns)}</div></div>${field('New value · blank means missing','editValue','Number or blank')}<button class="btn" type="submit">Save edited cell</button></form>`);$('#editDatasetForm').addEventListener('submit',e=>{e.preventDefault();busy(async()=>{let row=Number($('#editRow').value)-1,column=$('#editColumn').value,val=$('#editValue').value;if(!column)throw new Error('Choose a numeric column');if(!Number.isInteger(row)||row<0||row>=page.total)throw new Error('Invalid row number');if(val.trim()&&!Number.isFinite(Number(val)))throw new Error('Enter a finite number');await api(`/api/v05/datasets/${did}/edit-cell`,'POST',{row,column,value:val.trim()?Number(val):null});$('#modal').close();await refreshProject();navigate('data');notice('Working dataset changed. Analyses and chapters from older versions are stale.');schedulePreview()})});break;}
 case 'edit-path':{let index=Number(el.dataset.index),e=p.model.edges[index],m=p.model.nodes;let opts=m.map(n=>({value:n.id,label:n.label}));openModal('Edit hypothesis path',`<form id="pathForm"><div class="field"><label>Source construct</label>${selector('pathSource',opts,e.source)}</div><div class="field"><label>Target construct</label>${selector('pathTarget',opts,e.target)}</div><div class="field"><label>Effect</label>${selector('pathKind',[{value:'direct',label:'Direct'},{value:'moderation',label:'Moderation'}],e.kind||'direct')}</div><div class="field"><label>Moderator (when moderation)</label>${selector('pathModerator',opts,e.moderator||'')}</div><button class="btn" type="submit">Update hypothesis</button></form>`);$('#pathForm').onsubmit=event=>{event.preventDefault();busy(async()=>{let model=structuredClone(p.model),edge=model.edges[index];edge.source=$('#pathSource').value;edge.target=$('#pathTarget').value;edge.kind=$('#pathKind').value;edge.moderator=edge.kind==='moderation'?$('#pathModerator').value:undefined;if(edge.kind==='moderation'&&!edge.moderator)throw new Error('Select a moderator');await api(`/api/v09/projects/${p.id}`,'PATCH',{model});$('#modal').close();await refreshProject();navigate('model');schedulePreview();notice('Path edited; estimation refreshed')})};break;}
 case 'provenance-dataset':{let a=await api('/api/datasets/'+el.dataset.id+'/provenance');openModal('Original dataset provenance',`<p><b>${html(a.archive_status)}</b></p><p>SHA-256: <code>${html(a.sha256||'Not available for legacy imports')}</code></p><p class="hint">${html(a.original_name||'Original filename unavailable')} · ${html(a.byte_size||'unknown')} bytes</p><p class="hint">Original bytes are retained separately from the working CSV only for new v0.9.1 uploads. Legacy normalized files cannot recreate the uploaded bytes.</p>`);break;}
 case 'preview-dataset':{
  let d=await api('/api/datasets/'+el.dataset.id);
  const variables=d.columns.map((col,i)=>{
    const values=d.preview.map(row=>row[col]).filter(v=>v!==null&&v!==undefined&&String(v).trim()!=='');
    const example=values.length?String(values[0]).slice(0,70):'—';
    const likelyNumeric=values.length>0&&values.every(v=>Number.isFinite(Number(v)));
    return `<div class="variable-row"><span class="variable-index">${i+1}</span><div><strong>${html(col)}</strong><small>Contoh: ${html(example)}</small></div><span class="badge ${likelyNumeric?'current':''}">${likelyNumeric?'Tampak numerik':'Teks / campuran'}</span></div>`;
  }).join('');
  openModal('Variabel dataset · '+d.name,`<div class="callout">Terdeteksi <b>${d.columns.length} variabel</b> dalam <b>${d.rows} respons</b>. Klasifikasi numerik hanya berdasarkan beberapa baris contoh, bukan pemeriksaan keseluruhan kolom.</div><h3 class="sectiongap">Semua nama variabel</h3><div class="variable-list">${variables}</div><details><summary>Pratinjau 8 kolom pertama</summary>${statTable(d.columns.slice(0,8),d.preview.map(r=>d.columns.slice(0,8).map(c=>r[c]??'')))}</details><details><summary>Nilai kosong / missing</summary>${renderKV(d.missing)}</details>`);break;}

 case 'edit-dataset':{
  let did=el.dataset.id;
  let data=await api(`/api/v05/datasets/${did}/rows?offset=0&limit=10`);
  let cols=data.columns.slice(0,12);
  let hdr=['Row',...cols];
  let trs=data.rows.map((row,i)=>`<tr><td>${i+1}</td>${cols.map(c=>`<td><div class="row" style="min-width:122px;gap:4px"><input class="control" type="number" step="any" style="width:80px" data-editrow="${i}" data-editcolumn="${attr(c)}" value="${attr(row[c]??'')}"><button class="btn sm light" data-action="save-cell" data-row="${i}" data-column="${attr(c)}" data-dataset="${attr(did)}" title="Save this cell">✓</button></div></td>`).join('')}</tr>`).join('');
  openModal('Edit original dataset · numeric cells',`<div class="callout warning">Changes are written to a working CSV; the original CSV is backed up on first edit. Each edit invalidates previous SEM analyses and may alter results. Review values carefully. Showing first 10 rows and 12 numeric columns.</div><div class="tablewrap" style="margin-top:12px"><table><thead><tr>${hdr.map(c=>`<th>${html(c)}</th>`).join('')}</tr></thead><tbody>${trs}</tbody></table></div><p class="hint">Total: ${data.total} rows. Numeric columns only.</p>`);
  break;
 }
 case 'save-cell':{
  const did=el.dataset.dataset,row=Number(el.dataset.row),column=el.dataset.column;
  const editor=$$('[data-editrow]').find(x=>x.dataset.editrow===String(row)&&x.dataset.editcolumn===column);
  if(!editor)throw new Error('Cell editor not found');
  const value=editor.value.trim()===''?null:Number(editor.value);
  if(value!==null&&!Number.isFinite(value))throw new Error('Enter a valid number');
  await api(`/api/v05/datasets/${did}/edit-cell`,'POST',{row,column,value});
  if(p?.dataset_id===did){await refreshProject();notice('Value saved. All previous analyses are stale. Recalculate in SEM-PLS.')}else notice('Numeric value saved; original CSV backed up.');
  el.textContent='✓ Saved';el.classList.add('soft');break;
 }
 case 'link-dataset':{
    if(!p)throw new Error('Buat proyek terlebih dahulu.');
    if(p.dataset_id&&p.dataset_id!==el.dataset.id&&((p.model?.nodes?.length||0)>0||p.analysis)){
      openModal('Ganti dataset proyek?',`<div class="callout warning">Dataset baru akan mengganti dataset pada proyek <b>${html(p.name)}</b>. Model lama akan dikosongkan dan analisis sebelumnya menjadi tidak berlaku. Berkas dataset lama tetap tersimpan.</div><div class="row sectiongap"><button type="button" class="btn light" data-action="cancel-modal">Batal</button><button type="button" class="btn danger" data-action="confirm-link-dataset" data-id="${attr(el.dataset.id)}">Ya, ganti dataset & reset model</button></div>`);
      break;
    }
    await api(`/api/v09/projects/${p.id}`,'PATCH',{dataset_id:el.dataset.id,model:{nodes:[],edges:[]}});
    await refreshProject();navigate('data');notice('Dataset berhasil dihubungkan.');break;
  }
  case 'cancel-modal':$('#modal').close();break;
  case 'confirm-link-dataset':{
    if(!p)throw new Error('Proyek tidak ditemukan.');
    await api(`/api/v09/projects/${p.id}`,'PATCH',{dataset_id:el.dataset.id,model:{nodes:[],edges:[]}});
    $('#modal').close();await refreshProject();navigate('data');notice('Dataset diganti. Rancangan model harus dibuat ulang.');break;
  }

 case 'add-path':{let src=$('#edgeSource').value,dst=$('#edgeTarget').value;if(!src||!dst||src===dst)throw new Error('Choose two different constructs');let model=structuredClone(p.model);model.edges.push({source:src,target:dst,kind:'direct',label:'H'+(model.edges.length+1)});await api(`/api/v09/projects/${p.id}`,'PATCH',{model});await refreshProject();navigate('model');schedulePreview();break;}
 case 'remove-path':{let model=structuredClone(p.model);model.edges.splice(Number(el.dataset.index),1);await api(`/api/v09/projects/${p.id}`,'PATCH',{model});await refreshProject();navigate('model');schedulePreview();notice('Path removed; analysis marked stale');break;}
 case 'save-hypotheses':{let model=structuredClone(p.model);$$('[data-hlabel]').forEach(x=>model.edges[Number(x.dataset.hlabel)].label=x.value);await api(`/api/v09/projects/${p.id}`,'PATCH',{model});await refreshProject();schedulePreview();notice('Hypotheses saved. Recalculate SEM-PLS after model edits.');break;}
 case 'save-measurement':{let model=structuredClone(p.model);$$('[data-measure]').forEach(x=>model.nodes[Number(x.dataset.measure)].measurement=x.value);$$('[data-role]').forEach(x=>model.nodes[Number(x.dataset.role)].role=x.value);$$('[data-construct-label]').forEach(x=>model.nodes[Number(x.dataset.constructLabel)].label=x.value.trim());$$('[data-construct-indicators]').forEach(x=>model.nodes[Number(x.dataset.constructIndicators)].indicators=x.value.split(',').map(v=>v.trim()).filter(Boolean));await api(`/api/v09/projects/${p.id}`,'PATCH',{model});await refreshProject();navigate('model');schedulePreview();notice('Construct mapping saved; analysis marked stale');break;}
 case 'live-preview':{let x=await api(`/api/v09/projects/${p.id}/preview`,'POST',{});$('#liveResult').innerHTML=panel('Fast preview · descriptive only',`<div class="badge">${html(x.status)}</div>${statTable(['Path','β'],Object.entries(x.paths||{}).map(([k,v])=>[k,fmt(v)]))}<p class="hint">${html(x.notice)}</p>`);break;}
 case 'add-reference':openModal('Add a verified reference',`<form id="addRefForm">${field('Title','manualTitle','Article title')}${field('Authors','manualAuthors','Lastname, Firstname; …')}${field('Year','manualYear','2026','','number')}${field('Journal / publisher','manualVenue','Publication')}${field('DOI','manualDOI','10.xxxx/…')}${field('HTTPS URL','manualURL','https://…')}<button class="btn" type="submit">✓ Add to library</button></form>`);break;
 case 'remove-ref':if(!confirm('Remove this reference from the shared library?'))return;await api('/api/v05/references/'+el.dataset.id,'DELETE');await loadRefs();navigate(state.view);break;
 case 'evidence-map':{let x=await api(`/api/v09/projects/${p.id}/evidence`);let t=panel('Evidence mapping · title-only matching',`<div class="callout warning">${html(x.notice)}</div>${statTable(['Construct','Matches','Candidate titles'],x.construct_matrix.map(m=>[m.construct,m.title_matches,m.candidate_references.map(r=>r.title).join('; ')||'Not found']))}${sep}<h3>Research gap questions</h3>${x.research_gap_prompts.map(t=>`<p class="hint">• ${html(t)}</p>`).join('')}`);let holder=$('#evidenceMap');if(holder)holder.innerHTML=t;else openModal('Evidence map',t);break;}
 case 'cite':{let r=state.refs.find(r=>r.id===el.dataset.id);if(r){state.selectedRefs.add(r.id);insertCitation(citeText(r));let cb=$(`[data-select-ref="${CSS.escape(r.id)}"]`);if(cb)cb.checked=true}break;}
 case 'insert-bibliography':{let ed=$('#chapterEditor');if(!ed)throw new Error('Open a chapter editor first');if(ed.value.includes('[@bibliography]')){notice('Live bibliography marker is already present');break;}insertCitation('\n\n[@bibliography]\n');notice('Live bibliography placeholder inserted; it updates when citations change');break;}
 case 'save-chapter':{let body=$('#chapterEditor')?.value;if(!body?.trim())throw new Error('Write some text before saving');let n=state.chapter;const result=await api(`/api/v09/projects/${p.id}/chapters/${n}/save`,'POST',{body,reference_ids:[...state.selectedRefs],style:citationStyle()});state.editorDrafts[state.project.id+`:chapter${n}`]=body;await refreshProject();notice(result.citation_integrity==='unverified_plain_text'?`Chapter ${n} saved; review plain-text citations before submission`:`Chapter ${n} version saved successfully`);break;}
 case 'draft-versions':{let items=await api(`/api/v09/projects/${p.id}/chapters/${state.chapter}`);openModal('Chapter draft history',items.length?items.map(x=>`<div class="listitem"><div><b>${html(x.created_at.slice(0,19))}</b><small>${html(x.status)} · ${html(x.citation_style||'apa').toUpperCase()} · ${(x.reference_ids||[]).length} sources · ${x.body.length} characters</small></div><button class="btn sm light" data-action="restore-chapter" data-id="${attr(x.id)}">Load into editor</button></div>`).join(''):empty('No saved versions','Save a chapter draft to begin version tracking.'));state.chapterVersions=items;break;}
 case 'restore-chapter':{
 const d=state.chapterVersions.find(x=>x.id===el.dataset.id);if(!d)return;
 const n=state.chapter,key=state.project.id+`:chapter${n}`;
 const out=await api(`/api/v09/projects/${p.id}/chapters/${n}/versions/${d.id}/restore`,'POST',{});
 state.referenceSelections[key]=new Set(out.reference_ids);state.selectedRefs=new Set(out.reference_ids);
 state.currentCitationStyle=out.citation_style;delete state.editorDrafts[key];
 $('#modal').close();await refreshProject();await render();
 notice(out.warning||`Chapter ${n} restored as a new saved version (text, sources & ${out.citation_style.toUpperCase()}).`,!!out.warning);
 break;}
 case 'generate-chapter':{if(state.generation)return;let n=state.chapter,body={research_facts:$('#researchFacts').value,instructions:$('#writingInstructions').value,reference_ids:[...state.selectedRefs],style:$('#draftStyle').value,language:$('#draftLanguage').value,mode:$('#draftMode').value};state.generation=true;let gen=$('#generateBtn');gen.disabled=true;gen.innerHTML='<span class="loader"></span> '+(body.mode==='generate'?'Generating… up to 1h':'Preparing preview…');let holder=$('#generationResult');holder.innerHTML=hint(body.mode==='generate'?'Model is generating locally. Keep this tab and server running.':'Compiling citation-safe AI prompt…');try{let out=await api(`/api/v09/projects/${p.id}/chapters/${n}/draft`,'POST',body);if(body.mode==='preview'){holder.innerHTML=panel('AI prompt preview',`<p class="hint">No AI call was made. Review the precise evidence and method statements before generating.</p><textarea readonly class="control" rows="12">${html(out.prompt)}</textarea>`)}else{let text=out.body||'';state.editorDrafts[state.project.id+`:chapter${n}`]=text;$('#chapterEditor').value=text;wordCount();holder.innerHTML=hint('AI draft saved in history. Review all references, research procedures and result statements before submission.');await refreshProject();notice('AI draft completed and saved.')}}finally{state.generation=false;gen.disabled=false;gen.textContent='Preview / Generate chapter'}break;}
 case 'export-chapter-word':{location.href=`/api/v09/projects/${p.id}/chapters/${state.chapter}/docx`;notice('Exporting latest saved draft. Save current edits first.');break;}
 case 'download-word':{let content=ZRCitation.renderDocument($('#chapterEditor')?.value||'',citationStyle(),state.refs).text;if(content.trim().length<5)throw new Error('Write at least five characters first');let response=await fetch('/api/v05/chapters/export-word',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({chapter:state.chapter,body:content})});if(!response.ok)throw new Error('Word export unavailable');let url=URL.createObjectURL(await response.blob());let link=document.createElement('a');link.href=url;link.download=`Z-Research_Chapter_${state.chapter}_v09.docx`;link.click();setTimeout(()=>URL.revokeObjectURL(url),15000);break;}
 case 'download-chapter':{let text=ZRCitation.renderDocument($('#chapterEditor')?.value||'',citationStyle(),state.refs).text;let blob=new Blob([text],{type:'text/plain;charset=utf-8'});let url=URL.createObjectURL(blob);let link=document.createElement('a');link.href=url;link.download=`Z-Research_Chapter_${state.chapter}.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
 case 'use-news-query':{$('#newsQuery').value=el.dataset.query;$('#newsSearchForm').requestSubmit();break;}
 case 'find-phenomena':{let x=await api('/api/v05/phenomena/suggestions?dataset_id='+encodeURIComponent(p.dataset_id));$('#phenomenaResults').innerHTML=(x.themes||[]).map(t=>`<div class="newsrow"><b>${html(t.theme)}</b><small>Variables: ${html((t.variables||[]).join(', '))}</small><p class="hint">Exploratory suggestion only · no external trend verified</p><button class="btn light sm" data-action="use-news-query" data-query="${attr(t.news_query)}">Search related news</button></div>`).join('')||empty('No eligible themes','Check dataset column names.');break;}
 case 'delete-news':await api('/api/v05/news/'+el.dataset.id,'DELETE');navigate('chapter1');break;
 case 'export-provenance':location.href=`/api/v09/projects/${p.id}/reproducibility.json`;break;
 case 'disconnect-ai':await api('/api/ai/disconnect','POST',{});navigate('settings');notice('AI disconnected');break;
 case 'logout':await api('/api/auth/logout','POST',{});state.auth=null;state.project=null;state.projects=[];localStorage.removeItem('zr09_active_project');await showAuth();notice('Signed out');break;
 default:console.warn('Unhandled action',action);
}}
function openModal(title,body){$('#modalTitle').textContent=title;$('#modalContent').innerHTML=body;$('#modal').showModal()}
async function handleSubmit(form){let id=form.id,p=state.project;switch(id){
 case 'loginForm':{let status=await api('/api/auth/status');await api(status.configured?'/api/auth/login':'/api/auth/setup','POST',{username:$('#loginName').value,password:$('#loginPassword').value});state.auth=await api('/api/auth/status');await loadDataset();await loadProjects();await loadRefs();navigate('home');notice('Selamat datang di Z-Research');break;}
 case 'uploadForm':{
   const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Mengunggah data…';
   try{
     let fd=new FormData(form);let uploadedName=fd.get('file')?.name||'Proyek Penelitian';
     let a=await api('/api/datasets','POST',fd,true);await loadDataset();
     if(!state.project && $('#autoCreateProject')?.checked){
       const name=($('#quickProjectName')?.value||'').trim()||uploadedName.replace(/\.(csv|xlsx)$/i,'').replace(/[_-]+/g,' ').trim().slice(0,120)||'Penelitian Baru';
       try{const created=await api('/api/v09/projects','POST',{name,dataset_id:a.id});state.project=created;await loadProjects();navigate('model');notice('Data berhasil diunggah dan proyek dibuat. Lanjut pilih variabel.');}
       catch(error){navigate('data');notice('Data tersimpan, tetapi proyek belum dibuat: '+error.message,true);}
     }else{navigate('data');notice('Data berhasil diunggah: '+a.rows+' respons, '+a.columns.length+' kolom.');}
   }finally{submit.disabled=false;submit.textContent='Unggah data';}break;}

 case 'projectForm':{let name=$('#newProjectName').value,ds=$('#newProjectDataset').value;let p=await api('/api/v09/projects','POST',{name,dataset_id:ds||null});state.project=p;await loadProjects();navigate('model');notice('Project created');break;}
 case 'autoModelForm':{if(!pickMulti('independent').length)throw new Error('Pilih minimal satu variabel independen (X).');if(!$('#dependent')?.value)throw new Error('Pilih variabel dependen (Y).');let r=await api(`/api/v09/projects/${p.id}/auto-model`,'POST',{independent:pickMulti('independent'),dependent:$('#dependent').value,mediators:pickMulti('mediators'),moderators:pickMulti('moderators')});await refreshProject();navigate('model');schedulePreview();notice('Model generated; inspect all hypotheses and measurement modes');break;}
 case 'runAnalysisForm':{let button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Calculating…';try{let x=await api(`/api/v09/projects/${p.id}/analyze`,'POST',{bootstraps:Number($('#bootstrapSamples').value),seed:Number($('#analysisSeed').value)});await refreshProject();navigate('sem');notice('Analysis complete · '+x.result.n+' complete cases')}finally{button.disabled=false;button.textContent='Run SEM-PLS'}break;}
 case 'refSearchForm':{let q=$('#refQuery').value;let out=await api('/api/v05/references/search','POST',{query:q,limit:12});let arr=out.results||out.items||[];let existing=new Set(state.refs.map(r=>normalizeDoi(r.doi)).filter(Boolean));$('#refResults').innerHTML=arr.length?arr.map((r,i)=>{let saved=!!r.doi&&existing.has(normalizeDoi(r.doi));return `<div class="newsrow"><b>${html(r.title)}</b><small>${html(r.authors||'')} · ${html(r.year||'')} · ${html(r.doi||'')}</small><div class="buttonrow"><button class="btn sm ${saved?'light':'soft'}" data-action="add-found-ref" data-index="${i}" ${saved?'disabled':''}>${saved?'✓ Added to library':'+ Add Reference'}</button></div></div>`}).join(''):empty('No metadata found','Try different keywords or add the reference manually.');state.searchRefs=arr;break;}
 case 'addRefForm':{let obj={title:$('#manualTitle').value,authors:$('#manualAuthors').value,year:Number($('#manualYear').value)||null,venue:$('#manualVenue').value,doi:$('#manualDOI').value,url:$('#manualURL').value};let x=await api('/api/v05/references/manual','POST',obj);$('#modal').close();await loadRefs();navigate(state.view);notice(x.already_saved?'✓ Reference was already in your library':'✓ Reference added to library');break;}
 case 'newsSearchForm':{let x=await api('/api/v05/news/search','POST',{query:$('#newsQuery').value});$('#newsSearchResults').innerHTML=(x.results||[]).map((r,i)=>`<div class="newsrow"><b>${html(r.title)}</b><small>${html(r.source||'')} · ${html(r.published||'')}</small><p><a target="_blank" rel="noopener noreferrer" href="${attr(r.url)}">Open article ↗</a></p><button class="btn sm light" data-action="save-found-news" data-index="${i}">Save news lead</button></div>`).join('')||empty('No news found','Use another query, or save article links directly.');state.searchNews=x.results||[];break;}
 case 'addNewsForm':{await api('/api/v05/news','POST',{title:$('#newsTitle').value,url:$('#newsURL').value,source:$('#newsSource').value});navigate('chapter1');notice('News lead saved for verification');break;}
 case 'connectForm':{let out=await api('/api/ai/connect','POST',{provider:$('#providerSelect').value,model:$('#providerModel').value,api_key:$('#providerKey').value,base_url:$('#providerURL').value});notice('AI connected · '+out.model);navigate('settings');break;}
 case 'logoForm':{let fd=new FormData(form);let result=await api('/api/v05/branding/logo','POST',fd,true);notice('Branding image saved');loadLogo();break;}
}}
// Delegated controls survive view replacements without stacking event handlers.
document.addEventListener('click',e=>{let el=e.target.closest('[data-action],[data-view]');if(!el||el.disabled)return;if(el.dataset.view){navigate(el.dataset.view);return}if(el.dataset.action==='add-found-ref'){busy(async()=>{let x=state.searchRefs?.[Number(el.dataset.index)];if(!x)return;let saved=await api('/api/v05/references/manual','POST',{title:x.title,authors:x.authors||'',year:x.year||null,venue:x.venue||'',doi:x.doi||'',url:x.url||''});el.textContent='✓ Added to library';el.disabled=true;await loadRefs();notice(saved.already_saved?'Already saved':'Added to reference library')});return}if(el.dataset.action==='save-found-news'){busy(async()=>{let x=state.searchNews?.[Number(el.dataset.index)];if(!x)return;await api('/api/v05/news','POST',{title:x.title,url:x.url,source:x.source||'',published:x.published||''});el.disabled=true;el.textContent='✓ Saved';notice('News link saved as unverified lead')});return}busy(()=>handleAction(el.dataset.action,el))});
document.addEventListener('submit',e=>{if(!e.target?.id)return;e.preventDefault();busy(()=>handleSubmit(e.target))});
document.addEventListener('change',e=>{if(e.target.id==='draftStyle'){state.currentCitationStyle=e.target.value;citationPreview();}if(e.target.matches('[data-select-ref]')){let id=e.target.dataset.selectRef;e.target.checked?state.selectedRefs.add(id):state.selectedRefs.delete(id);citationPreview()}if(e.target.id==='projectPicker'){let id=e.target.value;if(!id)return;busy(async()=>{state.project=await api('/api/v09/projects/'+id);state.selectedRefs.clear();localStorage.setItem('zr09_active_project',id);paintPicker();navigate('home')})}});
document.addEventListener('input',e=>{if(e.target.id==='chapterRefFilter'){let q=e.target.value.toLowerCase();$$('#chapterReferenceList .refrow').forEach(n=>n.style.display=n.textContent.toLowerCase().includes(q)?'':'none')}if(e.target.id==='filterRefs'){let q=e.target.value.toLowerCase();$('#referenceList').innerHTML=libraryList(state.refs.filter(r=>JSON.stringify(r).toLowerCase().includes(q)))}});
document.addEventListener('dragstart',e=>{const n=e.target.closest('[data-drag-ref]');if(n){const r=state.refs.find(r=>r.id===n.dataset.dragRef);if(r){state.selectedRefs.add(r.id);const cb=$(`[data-select-ref="${CSS.escape(r.id)}"]`);if(cb)cb.checked=true;e.dataTransfer.setData('text/plain',citeText(r));citationPreview();}}});
document.addEventListener('dragover',e=>{if(e.target.id==='chapterEditor')e.preventDefault()});
document.addEventListener('drop',e=>{if(e.target.id==='chapterEditor'){e.preventDefault();let text=e.dataTransfer.getData('text/plain');insertCitation(text)}});
$('#projectPicker').addEventListener('change',()=>{});
$('#mobileMenu').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('.sidebar').classList.remove('open')});
document.addEventListener('change',e=>{if(e.target.id==='easyDatasetFile'){const out=$('#selectedFileName');if(out)out.textContent=e.target.files?.[0]?.name||'Klik di sini untuk memilih file';}});
$('#openSettings').addEventListener('click',()=>navigate('settings'));
$('#closeModal').addEventListener('click',()=>$('#modal').close());
async function loadLogo(){try{let r=await fetch('/api/v05/branding/logo',{credentials:'same-origin'});if(r.ok&&r.headers.get('content-type')?.startsWith('image/')){let blob=await r.blob();let img=$('#brandImage');img.src=URL.createObjectURL(blob);img.hidden=false;state.logoLoaded=true}}catch{}}
loadLogo();start();
